StructuredTextModel.Text:
//-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
//	NAME:				HE_FCx02_Drive_State
//	CREATOR:			Helgevold - William Veim
//
// REQUIREMENTS: Danfoss FC102 or FC202
// DESCRTIPTION: 	Generates a string with Status code and description
//-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
//  VERSION LOG:
//	 VERSION			DATE				SIGN						DESCRIPTION
//	 1.0.0				2025-02-25		William Veim			Initial release
//	 1.0.1				2026-01-05		William Veim			Added reverse running as input
//
//================================================================================================================================


// Initilize
Wrk_StatusValue.Wrd := Inp_InverterStatus;
Wrk_StateString := '';
Wrk_StateDescription := '';

IF Wrk_StatusValue.Bit[1] THEN
	Wrk_StateCode:='RDY';
	Wrk_StateDescription:='Ready';
END_IF;
IF Wrk_StatusValue.Bit[11] THEN
	Wrk_StateCode:='RUN';
	Wrk_StateDescription:='Running';
END_IF;
IF Inp_ReverseRunning THEN
	Wrk_StateCode:='REV';
	Wrk_StateDescription:='Reverse running';
END_IF;
IF Wrk_StatusValue.Bit[7] THEN
	Wrk_StateCode:='WRN';
	Wrk_StateDescription:='Warning active';
END_IF;
IF Wrk_StatusValue.Bit[6] THEN
	Wrk_StateCode:='FLT';
	Wrk_StateDescription:='Fault active';
END_IF;
IF Wrk_StatusValue.Bit[14] THEN
	Wrk_StateCode:='LIM';
	Wrk_StateDescription:='Torque limit';
END_IF;
IF NOT Wrk_StatusValue.Bit[8] AND Wrk_StatusValue.Bit[11] THEN
	Wrk_StateCode:='RMP';
	Wrk_StateDescription:='Ramping ongoing';
END_IF;
IF NOT Wrk_StatusValue.Bit[9] THEN
	Wrk_StateCode:='LOCAL';
	Wrk_StateDescription:='Local operation';
END_IF;
IF Wrk_StatusValue.Bit[6] THEN
	Wrk_StateCode:='TRP';
	Wrk_StateDescription:='Triplock';
END_IF;

// Add Status Code
IF TestABit(In:=Cfg_Composition, Pos:=0) THEN
	Wrk_StateString := CONCAT(Wrk_StateString, Wrk_StateCode);
END_IF;	

// Add State Description
IF TestABit(In:=Cfg_Composition, Pos:=1) THEN
	IF LEN(Wrk_StateString) > 0 THEN
		Wrk_StateString := CONCAT(Wrk_StateString, Cfg_Delimiter);
	END_IF;
	Wrk_StateString := CONCAT(Wrk_StateString, Wrk_StateDescription);
END_IF;

HE_FCx02_Drive_State := Wrk_StateString;
